// Builds the static airport dataset from OurAirports (public domain).
//   node scripts/build-airports.mjs [--force]
// Output (git-ignored, regenerated by `npm run build` when missing):
//   public/data/airports/index.json        compact search/map index
//   public/data/airports/detail/XX.json    runways + frequencies, sharded by ident prefix
//   public/data/countries.json             names, airport centroids and bounding boxes
import { existsSync, mkdirSync, rmSync, writeFileSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(ROOT, 'public', 'data');
const CACHE = join(ROOT, 'node_modules', '.cache', 'ourairports');
const BASE = 'https://davidmegginson.github.io/ourairports-data';
const FILES = ['airports.csv', 'runways.csv', 'airport-frequencies.csv', 'countries.csv'];

const force = process.argv.includes('--force');
if (!force && existsSync(join(OUT, 'airports', 'index.json'))) {
  console.log('airports: dataset present (use --force to rebuild)');
  process.exit(0);
}

// --- tiny RFC 4180 CSV parser -------------------------------------------------
function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else quoted = false;
      } else field += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') {
      row.push(field);
      field = '';
    } else if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && text[i + 1] === '\n') i++;
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
    } else field += ch;
  }
  if (field || row.length) {
    row.push(field);
    rows.push(row);
  }
  const [header, ...body] = rows;
  return body.filter((r) => r.length > 1).map((r) => Object.fromEntries(header.map((h, i) => [h, r[i] ?? ''])));
}

async function download(name) {
  mkdirSync(CACHE, { recursive: true });
  const path = join(CACHE, name);
  if (!force && existsSync(path)) return readFileSync(path, 'utf8');
  const res = await fetch(`${BASE}/${name}`, { headers: { 'User-Agent': 'ArnavFlightRadar-build/1.0' } });
  if (!res.ok) throw new Error(`${name}: HTTP ${res.status}`);
  const text = await res.text();
  writeFileSync(path, text);
  return text;
}

const n = (v) => {
  if (v === '' || v === undefined) return null;
  const x = Number(v);
  return Number.isFinite(x) ? x : null;
};
const r5 = (x) => Math.round(x * 1e5) / 1e5;

const TYPES = ['large_airport', 'medium_airport', 'small_airport', 'heliport', 'seaplane_base', 'balloonport', 'closed'];

console.log('airports: downloading OurAirports CSVs…');
const [aText, rText, fText, cText] = await Promise.all(FILES.map(download));
const airports = parseCsv(aText);
const runways = parseCsv(rText);
const freqs = parseCsv(fText);
const countries = parseCsv(cText);
console.log(`airports: ${airports.length} airports, ${runways.length} runways, ${freqs.length} frequencies`);

// Inclusion policy: every large/medium airport, plus small airports and heliports
// that have an ICAO/IATA/GPS code (i.e. are realistically searchable).
const included = airports.filter((a) => {
  if (!n(a.latitude_deg) && n(a.latitude_deg) !== 0) return false;
  if (a.type === 'large_airport' || a.type === 'medium_airport') return true;
  if (a.type === 'small_airport') return !!(a.icao_code || a.iata_code || /^[A-Z]{4}$/.test(a.gps_code));
  if (a.type === 'seaplane_base' || a.type === 'heliport') return !!(a.icao_code || a.iata_code);
  return false;
});

const rows = included.map((a) => [
  a.ident,
  a.icao_code || (/^[A-Z]{4}$/.test(a.ident) ? a.ident : ''),
  a.iata_code,
  a.name,
  a.municipality,
  a.iso_country,
  r5(Number(a.latitude_deg)),
  r5(Number(a.longitude_deg)),
  TYPES.indexOf(a.type),
  n(a.elevation_ft),
  a.scheduled_service === 'yes' ? 1 : 0,
]);

const byIdent = new Map(included.map((a) => [a.ident, a]));
const rwByAirport = new Map();
for (const r of runways) {
  if (!byIdent.has(r.airport_ident)) continue;
  const list = rwByAirport.get(r.airport_ident) ?? [];
  const o = {
    lighted: r.lighted === '1',
    closed: r.closed === '1',
  };
  const put = (k, v) => {
    if (v !== null && v !== '' && v !== undefined) o[k] = v;
  };
  put('leIdent', r.le_ident);
  put('heIdent', r.he_ident);
  put('lengthFt', n(r.length_ft));
  put('widthFt', n(r.width_ft));
  put('surface', r.surface);
  put('leHeadingDegT', n(r.le_heading_degT));
  put('heHeadingDegT', n(r.he_heading_degT));
  put('leLat', n(r.le_latitude_deg));
  put('leLon', n(r.le_longitude_deg));
  put('heLat', n(r.he_latitude_deg));
  put('heLon', n(r.he_longitude_deg));
  put('leElevationFt', n(r.le_elevation_ft));
  put('heElevationFt', n(r.he_elevation_ft));
  put('leDisplacedThresholdFt', n(r.le_displaced_threshold_ft));
  put('heDisplacedThresholdFt', n(r.he_displaced_threshold_ft));
  list.push(o);
  rwByAirport.set(r.airport_ident, list);
}
const frByAirport = new Map();
for (const f of freqs) {
  if (!byIdent.has(f.airport_ident)) continue;
  const mhz = n(f.frequency_mhz);
  if (mhz === null) continue;
  const list = frByAirport.get(f.airport_ident) ?? [];
  const o = { type: f.type || 'OTHER', mhz };
  if (f.description) o.description = f.description;
  list.push(o);
  frByAirport.set(f.airport_ident, list);
}

const shard = (ident) => ident.slice(0, 2).toUpperCase().replace(/[^A-Z0-9]/g, '_');
const shards = new Map();
for (const a of included) {
  const d = {
    ident: a.ident,
    name: a.name,
    country: a.iso_country,
    lat: r5(Number(a.latitude_deg)),
    lon: r5(Number(a.longitude_deg)),
    type: a.type,
    scheduled: a.scheduled_service === 'yes',
    runways: (rwByAirport.get(a.ident) ?? []).sort((x, y) => (y.lengthFt ?? 0) - (x.lengthFt ?? 0)),
    frequencies: (frByAirport.get(a.ident) ?? []).sort((x, y) => x.type.localeCompare(y.type)),
  };
  const icao = a.icao_code || (/^[A-Z]{4}$/.test(a.ident) ? a.ident : '');
  if (icao) d.icao = icao;
  if (a.iata_code) d.iata = a.iata_code;
  if (a.municipality) d.city = a.municipality;
  if (n(a.elevation_ft) !== null) d.elevationFt = n(a.elevation_ft);
  if (a.iso_region) d.region = a.iso_region;
  if (a.continent) d.continent = a.continent;
  if (/^https?:\/\//.test(a.home_link)) d.homeLink = a.home_link;
  if (/^https?:\/\/[a-z]+\.wikipedia\.org\//.test(a.wikipedia_link)) d.wikipedia = a.wikipedia_link;
  const k = shard(a.ident);
  const s = shards.get(k) ?? {};
  s[a.ident] = d;
  shards.set(k, s);
}

// Countries: centroid and bbox from their airports (no extra dataset needed).
const geo = new Map();
for (const a of included) {
  const lat = Number(a.latitude_deg);
  const lon = Number(a.longitude_deg);
  const g = geo.get(a.iso_country) ?? { lat: 0, lon: 0, k: 0, lats: [], lons: [] };
  const w = a.type === 'large_airport' ? 6 : a.type === 'medium_airport' ? 3 : 1;
  g.lat += lat * w;
  g.lon += lon * w;
  g.k += w;
  g.lats.push(lat);
  g.lons.push(lon);
  geo.set(a.iso_country, g);
}
const pct = (arr, p) => {
  const s = [...arr].sort((x, y) => x - y);
  return s[Math.min(s.length - 1, Math.max(0, Math.round((s.length - 1) * p)))];
};
const countryOut = countries
  .filter((c) => geo.has(c.code))
  .map((c) => {
    const g = geo.get(c.code);
    // 2nd–98th percentile bounds ignore far-flung overseas territories.
    return {
      code: c.code,
      name: c.name,
      continent: c.continent,
      lat: r5(g.lat / g.k),
      lon: r5(g.lon / g.k),
      bbox: [pct(g.lons, 0.02), pct(g.lats, 0.02), pct(g.lons, 0.98), pct(g.lats, 0.98)].map(r5),
    };
  })
  .sort((a, b) => a.name.localeCompare(b.name));

rmSync(join(OUT, 'airports'), { recursive: true, force: true });
mkdirSync(join(OUT, 'airports', 'detail'), { recursive: true });
const generatedAt = new Date().toISOString();
writeFileSync(
  join(OUT, 'airports', 'index.json'),
  JSON.stringify({ v: 1, generatedAt, source: 'OurAirports (public domain)', rows }),
);
// Major tier (large, medium, or scheduled service) loads at startup for the map
// layer and instant search; the full index loads on demand.
const majorRows = rows.filter((r) => r[8] <= 1 || r[10] === 1);
writeFileSync(
  join(OUT, 'airports', 'index-major.json'),
  JSON.stringify({ v: 1, generatedAt, source: 'OurAirports (public domain)', rows: majorRows }),
);
for (const [k, s] of shards) writeFileSync(join(OUT, 'airports', 'detail', `${k}.json`), JSON.stringify(s));
writeFileSync(join(OUT, 'countries.json'), JSON.stringify({ v: 1, generatedAt, countries: countryOut }));
console.log(`airports: wrote ${rows.length} index rows (${majorRows.length} major), ${shards.size} detail shards, ${countryOut.length} countries`);
